    en: {
      title: `International GPA Calculator`,
      intro: `This calculator works out a GPA on the 4.0 and 5.0 scales used in university applications abroad. Enter each course's grade and credit, pick a scale, and the tool takes a credit-weighted average. It can also convert a GPA from one scale to the other.`,
      howTo: [
        `Choose a scale — 4.0 or 5.0.`,
        `Choose each course's grade.`,
        `Enter each course's credit.`,
        `Read the GPA, or convert it to the other scale.`,
      ],
      formula: `Formula: 4.0 scale — A 4.0, A− 3.7, B+ 3.3, B 3.0, B− 2.7, C+ 2.3, C 2.0, C− 1.7, D+ 1.3, D 1.0, F 0. 5.0 scale — A 5.0, B 4.0, C 3.0, D 2.0, F 0. GPA = sum(point × credit) ÷ total credits. Scale conversion is by proportion.`,
      example: `Example: on the 4.0 scale, three courses — (4.0, 3 credits), (3.0, 3 credits), (3.7, 2 credits). Calculation: (12 + 9 + 7.4) ÷ 8 = 28.4 ÷ 8 = 3.55.`,
      faq: [
        { q: `What is the difference between the 4.0 and 5.0 scales?`, a: `The 4.0 scale is most used in the USA, and the 5.0 scale is used for weighted grades in some countries. Use the scale your application asks for.` },
        { q: `Is the scale conversion exact?`, a: `It is by proportion (for example, a 4.0-scale GPA times 5 divided by 4). It is an estimate — a university's own rule may differ.` },
        { q: `Can I use NU grades here?`, a: `No, the NU scale is different (A+ 4.00, A 3.75). For NU, use the NU CGPA Calculator.` },
        { q: `Is this an official GPA?`, a: `No, it is a calculation from the data you enter. Check the university's rules before applying.` },
      ],
    },
