      intro: `এই টুলে প্রতিদিন একটি কুরআনের আয়াত দেখানো হয় — আরবি লেখা, বাংলা অর্থ ও ইংরেজি অর্থসহ। ৩০টি সুপরিচিত ছোট আয়াতের তালিকা থেকে বছরের দিন অনুযায়ী আয়াত বাছা হয়, তাই একই দিনে সবাই একই আয়াত দেখে।`,
