      intro: `কিউআর কোড রিডার দিয়ে ছবি থেকে কিউআর কোড পড়া যায়। ছবির ফাইল আপলোড করাই মূল উপায় (সর্বোচ্চ ১০ MB) — ক্যামেরা শুধু ঐচ্ছিক, আপনার অনুমতি ছাড়া চালু হয় না। পড়া তথ্য অনুযায়ী কাজের বোতাম দেখানো হয় — লিংক খোলা, কল করা, ইমেইল করা। ওয়াইফাই কিউআর কোড পড়লেও ফোন নিজে থেকে যুক্ত হয় না। সব কাজ ব্রাউজারেই হয়।`,
